INSERT INTO creators (id, slug, name, source, trusted, published, catalog_hash, created_at, updated_at) VALUES ('autostacc', 'autostacc', 'AutoStacc', 'catalog', 1, 1, 'e5593688e5474ff7', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET slug = excluded.slug, name = excluded.name, source = excluded.source, trusted = excluded.trusted, published = excluded.published, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE creators.source = 'catalog' AND (creators.catalog_hash IS NOT excluded.catalog_hash OR creators.deleted_at IS NOT NULL);
UPDATE creators SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE source = 'catalog' AND deleted_at IS NULL AND id NOT IN ('autostacc');
INSERT INTO projects (id, name, features, published, creator_id, slug, source, tagline, image, genres, look, catalog_hash, created_at, updated_at) VALUES ('glitches-and-stitches', 'Glitches & Stitches', '["releases","events","store","polls","relationships"]', 1, 'autostacc', 'glitches-and-stitches', 'catalog', 'An electronic music project that treats unfinished songs as raw material: fragments are torn out, stitched into new tracks and glitched into something new.', '/img/projects/glitches-and-stitches/icon.png', '["genre:electronic","genre:edm"]', '{"skin":true,"sounds":true,"entity":"MusicGroup"}', '37b96cd6e5c44d24', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'))
  ON CONFLICT (id) DO UPDATE SET name = excluded.name, features = excluded.features, published = excluded.published, creator_id = excluded.creator_id, slug = excluded.slug, source = excluded.source, tagline = excluded.tagline, image = excluded.image, genres = excluded.genres, look = excluded.look, catalog_hash = excluded.catalog_hash, deleted_at = NULL, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now')
  WHERE projects.source = 'catalog' AND (projects.catalog_hash IS NOT excluded.catalog_hash OR projects.deleted_at IS NOT NULL);
UPDATE projects SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE source = 'catalog' AND deleted_at IS NULL AND id NOT IN ('glitches-and-stitches');
UPDATE polls SET published = 0, deleted_at = strftime('%Y-%m-%dT%H:%M:%fZ','now'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE deleted_at IS NULL;
